players.script:
# thrower.pf — grappler.
# Strategy: close the distance and throw. Throws ignore blocks, so this beats
# defensive scripts, but any attack interrupts a throw in startup. After 5
# throws in a row it mixes in a punch, so its throws never go stale.
loop {
  if in_range(throw) {
    throw
    if repeats >= 5 { punch }
  } else {
    move_forward x3
  }
}
on_hit { move_forward x2 }

# rushdown.pf — relentless pressure.
# Strategy: walk in fast and keep attacking. Kick from max range, follow up
# with a punch, and mix in a sweep against blockers.
loop {
  if in_range(kick) {
    kick
    if enemy.blocking { sweep } else { punch }
  } else {
    move_forward x4
  }
}
